import {createPortableCamp} from './portable-camp-world.mjs';
import * as T from './vendor/three.module.js';
import {createPracticalLighting} from './practical-lighting.mjs';
import {environmentLight} from './alpine-weather.mjs';
export function createWeatherWorld(scene,{compact=false,region='alp',height=()=>0,interactive=[],paths=[],colliders=[]}={}){
 const portableCamp=createPortableCamp(scene,height,region);const practical=createPracticalLighting(scene,{compact,region,height,interactive,paths,colliders});
 const root=new T.Group();root.userData.kind='dynamic-alpine-weather';scene.add(root);const count=compact?220:480,p=new Float32Array(count*3),rain=new Float32Array(count*6);let seed=719;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};for(let i=0;i<count;i++){p[i*3]=(rnd()-.5)*42;p[i*3+1]=rnd()*24;p[i*3+2]=(rnd()-.5)*42;}
 const sg=new T.BufferGeometry();sg.setAttribute('position',new T.BufferAttribute(p,3));const snow=new T.Points(sg,new T.PointsMaterial({color:'#edf3f4',size:.11,transparent:true,opacity:0,depthWrite:false}));root.add(snow);const rg=new T.BufferGeometry();rg.setAttribute('position',new T.BufferAttribute(rain,3));const drops=new T.LineSegments(rg,new T.LineBasicMaterial({color:'#c6dbe8',transparent:true,opacity:0,depthWrite:false}));root.add(drops);
 const starsG=new T.BufferGeometry(),sp=[];for(let i=0;i<340;i++){const a=rnd()*Math.PI*2,y=.12+rnd()*.85,r=Math.sqrt(1-y*y);sp.push(Math.cos(a)*r*470,y*470,Math.sin(a)*r*470);}starsG.setAttribute('position',new T.Float32BufferAttribute(sp,3));const stars=new T.Points(starsG,new T.PointsMaterial({size:1.05,color:'#f2ecda',transparent:true,opacity:0,depthWrite:false,fog:false}));scene.add(stars);
 const moon=new T.Mesh(new T.SphereGeometry(4,12,8),new T.MeshBasicMaterial({color:'#ebe8cd',fog:false}));moon.position.set(140,190,-270);scene.add(moon);const moonlight=new T.DirectionalLight('#a6c4e9',0);moonlight.position.copy(moon.position);scene.add(moonlight);
 const lights=[];scene.traverse(o=>{if(o.isHemisphereLight||o.isDirectionalLight&&o!==moonlight)lights.push({o,intensity:o.intensity,color:o.color.clone()});});const sky=scene.children.find(o=>o.userData.kind==='alpine-daylight-sky');const skyDay=sky?.material.color.clone();let time=0;
 return{practical,step(dt,e,actor,indoors=false,camp=null){time+=dt;const v=environmentLight(e,actor.y);practical.step(v,actor,indoors);portableCamp.sync(camp,v.night,time);const dark=new T.Color('#081526'),day=new T.Color('#abc5d5'),haze=new T.Color('#b4bebc');scene.background?.copy(dark).lerp(day,v.day).lerp(haze,v.cloud*.5);scene.fog?.color.copy(scene.background);if(sky){sky.material.color.copy(dark).lerp(skyDay,v.day);sky.material.color.lerp(new T.Color('#858e98'),v.cloud*.45);}for(const l of lights){l.o.intensity=l.intensity*(l.o.isHemisphereLight?.26+v.day*.74:Math.max(.06,v.sun)*(1-v.cloud*.6));l.o.color.copy(l.color).lerp(new T.Color('#b8c9e5'),v.night*.45);if(l.o.isDirectionalLight)l.o.position.set(Math.cos(e.minute/1440*Math.PI*2)*48,Math.max(8,Math.abs(v.sun)*55),28);}moon.visible=v.night>.05;moonlight.intensity=v.night*.32;stars.material.opacity=v.night*(1-v.cloud*.9);root.visible=!indoors;root.position.set(actor.x,actor.y,actor.z);snow.material.opacity=v.snow*.75;drops.material.opacity=v.rain*.45;for(let i=0;i<count;i++){const k=i*3;p[k+1]-=dt*(v.rain>v.snow?19:1.1);if(p[k+1]<0)p[k+1]+=24;p[k]+=Math.sin(time*.8+i)*dt*.15;if(p[k]>21)p[k]=-21;rain[i*6]=p[k];rain[i*6+1]=p[k+1];rain[i*6+2]=p[k+2];rain[i*6+3]=p[k]+.13;rain[i*6+4]=p[k+1]+.7;rain[i*6+5]=p[k+2];}sg.attributes.position.needsUpdate=rg.attributes.position.needsUpdate=true;return v;}};
}
